import {safe,uid,filePicker,toast,clamp} from '../app/utils.js';
import {sanitizeSVG,svgBitmap} from './svg.js';
export const BLENDS=['source-over','screen','multiply','overlay','lighten','difference'];
export function newLayer(type){return {id:uid(),type,name:type==='system'?'GENERATIVE SYSTEM':type.toUpperCase(),visible:true,locked:false,opacity:1,blend:'source-over',x:0,y:0,scale:1,rotation:0,motion:'none',motionAmount:.15,motionSpeed:1,text:'DESIGN ON\nYOUR OWN TERMS',color:'#f2ebe7',color2:'#7e2844',size:.09};}
export function normalizeLayers(layers){if(!Array.isArray(layers)||!layers.length)return [newLayer('system')];return layers.slice(0,16).filter(l=>['system','text','image','gradient'].includes(l.type)).map(l=>{const out={...newLayer(l.type),...l};out.id=/^[a-zA-Z0-9-]{1,80}$/.test(out.id)?out.id:uid();for(const color of ['color','color2'])if(!/^#[0-9a-f]{6}$/i.test(out[color]))out[color]=color==='color'?'#f2ebe7':'#7e2844';for(const [key,lo,hi]of [['opacity',0,1],['x',-1,1],['y',-1,1],['scale',.1,3],['rotation',-180,180],['motionAmount',0,.5],['motionSpeed',0,3],['size',.02,.3]])out[key]=Number.isFinite(out[key])?clamp(out[key],lo,hi):newLayer(l.type)[key];out.blend=BLENDS.includes(out.blend)?out.blend:'source-over';return out;});}
export class Composer{
 constructor(lab){this.lab=lab;this.assets=new Map();}
 get layers(){return this.lab.state.layers;}
 mount(){const lab=this.lab,root=lab.root.querySelector('.inspector-content'),panel=document.createElement('div');panel.className='inspector-block composer-panel';panel.innerHTML=this.html();root.prepend(panel);
 panel.addEventListener('click',async e=>{const b=e.target.closest('[data-compose-action]');if(!b)return;const [action,id]=b.dataset.composeAction.split(':'),l=this.layers.find(l=>l.id===id);if(action==='select'){lab.state.selectedLayer=id;this.refresh();return;}if(action==='add-image'){if(this.lab.recorder)return toast('STOP RECORDING BEFORE IMPORTING');const [file]=await filePicker('image/png,image/jpeg,image/webp,image/svg+xml');if(file)await this.importFile(file);return;}if(this.lab.recorder)return toast('STOP RECORDING BEFORE EDITING LAYERS');if(action==='shape'){const [file]=await filePicker('.svg');if(file)await this.importShape(file);return;}
 if(l?.locked&&!['lock','visible'].includes(action))return;lab.capture();if(action==='add-text'||action==='add-gradient'){if(this.layers.length>=16)return toast('MAXIMUM 16 LAYERS');const layer=newLayer(action.slice(4));this.layers.push(layer);lab.state.selectedLayer=layer.id;}
 else if(l){const index=this.layers.indexOf(l);if(action==='visible')l.visible=!l.visible;else if(action==='lock')l.locked=!l.locked;else if(action==='delete'){this.layers.splice(index,1);if(!this.layers.length)this.layers.push(newLayer('system'));}else if(action==='duplicate'){if(this.layers.length>=16)return;const copy={...l,id:uid(),name:l.name+' COPY'};this.layers.splice(index+1,0,copy);}else if(action==='up'&&index<this.layers.length-1)[this.layers[index],this.layers[index+1]]=[this.layers[index+1],this.layers[index]];else if(action==='down'&&index>0)[this.layers[index],this.layers[index-1]]=[this.layers[index-1],this.layers[index]];else if(action==='reset')Object.assign(l,{x:0,y:0,scale:1,rotation:0,opacity:1,motion:'none'});}
 this.refresh();lab.onUpdate();});
 panel.querySelectorAll('[data-compose-field]').forEach(el=>{el.onfocus=()=>lab.capture();el.oninput=()=>{const layer=this.layers.find(l=>l.id===lab.state.selectedLayer);if(!layer||layer.locked)return;const key=el.dataset.composeField;layer[key]=['range','number'].includes(el.type)?Number(el.value):el.value;const value=panel.querySelector(`[data-compose-value="${key}"]`);if(value)value.textContent=Number(el.value).toFixed(2);lab.onUpdate();};});
 }
 refresh(){this.lab.root.querySelector('.composer-panel')?.remove();this.mount();}
 html(){const s=this.lab.state,l=this.layers.find(l=>l.id===s.selectedLayer)||this.layers.at(-1);s.selectedLayer=l?.id;const range=(key,label,min,max,step=.01)=>`<label class="input-label">${label}<output data-compose-value="${key}">${Number(l[key]).toFixed(2)}</output><input data-compose-field="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${l[key]}" ${l.locked?'disabled':''}></label>`;return `<div class="block-heading">VISUAL COMPOSER <span>${this.layers.length}/16</span></div><div class="composer-add"><button class="toolbtn" data-compose-action="add-text">+ TYPE</button><button class="toolbtn" data-compose-action="add-image">+ IMAGE / SVG</button><button class="toolbtn" data-compose-action="add-gradient">+ GRADIENT</button><button class="toolbtn" data-compose-action="shape">SVG → PARTICLES</button></div><div class="composer-layers">${[...this.layers].reverse().map(layer=>`<div class="composer-row ${layer.id===s.selectedLayer?'selected':''}"><button data-compose-action="visible:${layer.id}" title="Visibility">${layer.visible?'●':'○'}</button><button class="composer-name" data-compose-action="select:${layer.id}">${safe(layer.name)}${layer.type==='image'&&!this.assets.has(layer.assetId)?' / RELINK':''}</button><button data-compose-action="lock:${layer.id}" title="Lock">${layer.locked?'▣':'□'}</button><button data-compose-action="up:${layer.id}" title="Move up">↑</button><button data-compose-action="down:${layer.id}" title="Move down">↓</button><button data-compose-action="duplicate:${layer.id}" title="Duplicate">⧉</button><button data-compose-action="delete:${layer.id}" title="Delete">×</button></div>`).join('')}</div>${l?`<details open><summary>LAYER / ${safe(l.name)}</summary>${range('opacity','OPACITY',0,1)}<label class="input-label">BLEND<select data-compose-field="blend" ${l.locked?'disabled':''}>${BLENDS.map(b=>`<option value="${b}" ${l.blend===b?'selected':''}>${b.toUpperCase()}</option>`).join('')}</select></label>${l.type==='text'?`<label class="input-label">TEXT<textarea data-compose-field="text" maxlength="300" ${l.locked?'disabled':''}>${safe(l.text)}</textarea></label>${range('size','TYPE SIZE',.02,.3)}`:''}${['text','gradient'].includes(l.type)?`<label class="input-label">COLOR<input type="color" data-compose-field="color" value="${l.color}" ${l.locked?'disabled':''}></label>`:''}${l.type==='gradient'?`<label class="input-label">SECOND COLOR<input type="color" data-compose-field="color2" value="${l.color2}" ${l.locked?'disabled':''}></label>`:''}<details><summary>TRANSFORM / MOTION</summary>${range('x','POSITION X',-1,1)}${range('y','POSITION Y',-1,1)}${range('scale','SCALE',.1,3)}${range('rotation','ROTATION',-180,180,1)}<label class="input-label">MOTION SOURCE<select data-compose-field="motion" ${l.locked?'disabled':''}>${['none','time','loop','lfo','noise','cursor'].map(m=>`<option value="${m}" ${l.motion===m?'selected':''}>${m.toUpperCase()}</option>`).join('')}</select></label>${range('motionAmount','MOTION AMOUNT',0,.5)}${range('motionSpeed','MOTION SPEED',0,3)}<button class="toolbtn full" data-compose-action="reset:${l.id}" ${l.locked?'disabled':''}>RESET TRANSFORM</button></details></details>`:''}<p class="micro-note">Layers render into both PNG and WebM. Image files require relinking after restoring a project. Import the same filename to relink.</p>${s.shapeSVG?'<p class="micro-note">CUSTOM SVG PARTICLES / VECTOR EMBEDDED</p>':''}`;}
 async importFile(file,{bridge=false}={}){if(file.size>16*1024*1024)return toast('IMAGE LIMIT: 16 MB','error');try{const isSVG=/svg/i.test(file.type)||/\.svg$/i.test(file.name),svg=isSVG?sanitizeSVG(await file.text()):null,bitmap=svg?await svgBitmap(svg):await createImageBitmap(file);const existing=this.layers.find(l=>l.type==='image'&&l.sourceName===file.name&&!this.assets.has(l.assetId));this.lab.capture();let l=existing||newLayer('image');if(!existing){if(this.layers.length>=16){bitmap.close?.();return;}l.name=file.name.slice(0,50);l.sourceName=file.name;l.assetId=uid();if(svg)l.svg=svg;if(bridge){this.layers.unshift(l);for(const layer of this.layers)if(layer.type==='system'){layer.blend='screen';layer.opacity=.7;}}else this.layers.push(l);}this.assets.set(l.assetId,bitmap);this.lab.state.selectedLayer=l.id;this.refresh();this.lab.onUpdate();toast(existing?'SOURCE RELINKED':'COMPOSITION LAYER ADDED');}catch(error){toast('IMPORT FAILED: '+error.message,'error');}}
 async importShape(file){try{const svg=sanitizeSVG(await file.text()),image=await svgBitmap(svg);this.lab.capture();const s=this.lab.state;s.shapeSVG=svg;s.shapeName=file.name;s.sceneId='reactive-typography';s.variants[s.sceneId]=11;s.text=file.name;s.interactions[s.sceneId]={mode:'repel'};this.shapeImage=image;this.lab.render();this.lab.onUpdate();}catch(error){toast('SVG IMPORT: '+error.message,'error');}}
 shapeTexture(){if(!this.shapeImage)return null;if(this.textureSource!==this.shapeImage){this.textureSource=this.shapeImage;const c=document.createElement('canvas');c.width=1024;c.height=512;c.getContext('2d').drawImage(this.shapeImage,256,0,512,512);this.particleTexture=c;}return this.particleTexture;}
 async restoreAssets(){for(const layer of this.layers)if(layer.svg&&!this.assets.has(layer.assetId)){try{this.assets.set(layer.assetId,await svgBitmap(layer.svg));}catch{}}if(this.lab.state.shapeSVG){try{this.shapeImage=await svgBitmap(this.lab.state.shapeSVG);this.lab.updateText();}catch(error){toast('SVG RESTORE: '+error.message,'error');}}}
 render(source,target,time,pointer){if(target.width!==source.width||target.height!==source.height){target.width=source.width;target.height=source.height;}const w=target.width,h=target.height,g=target.getContext('2d',{alpha:true});g.clearRect(0,0,w,h);g.fillStyle='#08090c';g.fillRect(0,0,w,h);
 for(const l of this.layers){if(!l.visible||l.opacity<=0)continue;const t=time*l.motionSpeed,a=l.motionAmount;let x=l.x,y=l.y,angle=l.rotation*Math.PI/180,scale=l.scale;if(l.motion==='time')angle+=t*a;else if(l.motion==='loop'){x+=Math.cos(t)*a;y+=Math.sin(t)*a;}else if(l.motion==='lfo')scale*=1+Math.sin(t)*a;else if(l.motion==='noise'){x+=(Math.sin(t*.71)+Math.sin(t*1.31)*.4)*a;y+=(Math.cos(t*.53)+Math.sin(t*.97)*.4)*a;}else if(l.motion==='cursor'){x+=(pointer[0]-.5)*a*2;y-=(pointer[1]-.5)*a*2;}
 g.save();g.globalAlpha=l.opacity;g.globalCompositeOperation=l.blend;g.translate(w*(.5+x),h*(.5+y));g.rotate(angle);g.scale(scale,scale);
 if(l.type==='system')g.drawImage(source,-w/2,-h/2,w,h);else if(l.type==='image'){const image=this.assets.get(l.assetId);if(image){const fit=Math.min(w/image.width,h/image.height);g.drawImage(image,-image.width*fit/2,-image.height*fit/2,image.width*fit,image.height*fit);}}
 else if(l.type==='gradient'){const gradient=g.createLinearGradient(-w/2,-h/2,w/2,h/2);gradient.addColorStop(0,l.color);gradient.addColorStop(1,l.color2);g.fillStyle=gradient;g.fillRect(-w/2,-h/2,w,h);}
 else if(l.type==='text'){g.font=`900 ${h*l.size}px Arial`;g.textAlign='center';g.textBaseline='middle';g.fillStyle=l.color;const lines=String(l.text).split('\n').slice(0,12);lines.forEach((text,i)=>g.fillText(text,0,(i-(lines.length-1)/2)*h*l.size*1.1,w*.94));}g.restore();}
 }
 dispose(){for(const image of this.assets.values())image.close?.();this.assets.clear();this.shapeImage=null;this.particleTexture=null;}
}
